public class Loan {
    private float interest;

    // Default constructor
    Loan() {
        interest = 8.5f;
    }

    // Method 1: calculateEMI with two parameters
    public double calculateEMI(int tenure, double principal) {
        double simpleInterest = (principal * interest * tenure) / 100;
        return (simpleInterest + principal) / tenure;
    }

    // Method 2: calculateEMI with parameter order changed
    public double calculateEMI(double principal, int tenure) {
        double simpleInterest = (principal * interest * tenure) / 100;
        return (simpleInterest + principal) / tenure;
    }

    // Method 3: calculateEMI with three parameters
    public double calculateEMI(int tenure, double principal, float interest) {
        double simpleInterest = (principal * interest * tenure) / 100;
        return (simpleInterest + principal) / tenure;
    }

    public static void main(String[] args) {
        Loan loan = new Loan();
        // Overloaded methods
        double result = loan.calculateEMI(20000d, 5);
        double value = loan.calculateEMI(5, 20000d);
        double val = loan.calculateEMI(5, 20000, 9.5f);
        System.out.println("EMI per year is: " + result);
        System.out.println("EMI per year is: " + value);
        System.out.println("EMI per year is: " + val);
    }
}

class Loan {
    public void calculateEMI(double principal) {
        System.out.println("EMI calculation in Loan class");
    }
}

class HomeLoan extends Loan {
    // Overriding the method in Loan class
    @Override
    public void calculateEMI(double principal) {
        System.out.println("EMI calculation in HomeLoan class");
    }
}

public class ExecuteLoan {
    public static void main(String[] args) {
        Loan loan;
        HomeLoan h1 = new HomeLoan();

        loan = h1;  // Parent class reference holding child class object
        loan.calculateEMI(200000);  // Calls the overridden method in HomeLoan class
    }
}

